use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\Schema;

Schema::create('broadcast_subscribers', function (Blueprint $t): void {
    $t->id();
    $t->string('bot_id');
    $t->bigInteger('chat_id');
    $t->boolean('active')->default(false);
    $t->boolean('reachable')->default(true);
    $t->timestamp('consented_at')->nullable();
    $t->unique(['bot_id', 'chat_id']);
});
Schema::create('broadcast_campaigns', function (Blueprint $t): void {
    $t->id();
    $t->string('bot_id');
    $t->text('text');
    $t->string('status')->default('draft');
});
Schema::create('broadcast_deliveries', function (Blueprint $t): void {
    $t->id();
    $t->foreignId('campaign_id')->constrained('broadcast_campaigns');
    $t->foreignId('subscriber_id')->constrained('broadcast_subscribers');
    $t->string('status')->default('pending');
    $t->unsignedInteger('attempts')->default(0);
    $t->timestamp('available_at');
    $t->timestamp('started_at')->nullable();
    $t->bigInteger('message_id')->nullable();
    $t->string('last_error')->nullable();
    $t->unique(['campaign_id', 'subscriber_id']);
    $t->index(['status', 'available_at']);
});
Schema::create('broadcast_limits', function (Blueprint $t): void {
    $t->string('bot_id')->primary();
    $t->timestamp('next_send_at');
});

use Illuminate\Support\Facades\DB;

if (trim($text) === '' || strlen(mb_convert_encoding($text, 'UTF-16LE', 'UTF-8')) / 2 > 3000) {
    throw new InvalidArgumentException('Текст пустой или превышает бюджет длины.');
}
$campaignId = DB::transaction(function () use ($botId, $text): int {
    DB::table('broadcast_limits')->insertOrIgnore([
        'bot_id' => $botId, 'next_send_at' => now(),
    ]);
    $id = DB::table('broadcast_campaigns')->insertGetId([
        'bot_id' => $botId, 'text' => $text, 'status' => 'draft',
    ]);
    DB::table('broadcast_subscribers')->where('bot_id', $botId)
        ->where('active', true)->where('reachable', true)
        ->orderBy('id')->chunkById(500, function ($subscribers) use ($id): void {
            $rows = [];
            foreach ($subscribers as $subscriber) {
                $rows[] = [
                    'campaign_id' => $id, 'subscriber_id' => $subscriber->id,
                    'status' => 'pending', 'available_at' => now(),
                ];
            }
            DB::table('broadcast_deliveries')->insert($rows);
        });
    DB::table('broadcast_campaigns')->where('id', $id)->update(['status' => 'running']);
    return $id;
});

use App\Jobs\SendBroadcastRecipient;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schedule;

Schedule::call(function (): void {
    $bots = DB::table('broadcast_campaigns')->where('status', 'running')
        ->distinct()->pluck('bot_id');
    foreach ($bots as $botId) {
        $id = DB::table('broadcast_deliveries as d')
            ->join('broadcast_campaigns as c', 'c.id', '=', 'd.campaign_id')
            ->join('broadcast_limits as l', 'l.bot_id', '=', 'c.bot_id')
            ->where('l.next_send_at', '<=', now())
            ->where('c.bot_id', $botId)->where('c.status', 'running')
            ->where('d.status', 'pending')->where('d.available_at', '<=', now())
            ->orderBy('d.id')->value('d.id');
        if ($id !== null) {
            SendBroadcastRecipient::dispatch((int) $id)->onQueue('telegram-broadcast');
        }
    }
})->everySecond();
